  var minV = 2.10, maxV = 3.30;
  var rng = maxV - minV;

  function xp(i){return ML + (i/(n-1))*PW;}
  function yp(v){return MT + PH*(1-(v-minV)/rng);}

  function el(tag,attrs,txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs){e.setAttribute(k,attrs[k]);}
    if(txt!==undefined){e.textContent=txt;}
    return e;
  }

  var ticks = [2.25,2.50,2.75,3.00,3.25];
  for(var i=0;i<ticks.length;i++){
    var ty = yp(ticks[i]);
    svg.appendChild(el("line",{x1:ML,x2:ML+PW,y1:ty,y2:ty,stroke:"#ececec","stroke-width":"0.5"}));
    var lab = ticks[i].toFixed(2)+"%";
    svg.appendChild(el("text",{x:ML-6,y:ty+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},lab));
  }

  // Shaded region: Feb Hormuz
  var hx1 = xp(7), hx2 = xp(9);
  svg.appendChild(el("rect",{x:hx1,y:MT,width:hx2-hx1,height:PH,fill:"#c0392b","fill-opacity":"0.05"}));
  svg.appendChild(el("text",{x:hx1+4,y:MT+11,"font-size":"7","fill":"#8a3030","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"Hormuz"));

  // GoC 5Y line
  var pts5 = goc.map(function(d,i){return xp(i)+","+yp(d.v);}).join(" ");
  var line5 = document.createElementNS("http://www.w3.org/2000/svg","polyline");
  line5.setAttribute("points",pts5);
  line5.setAttribute("fill","none");
  line5.setAttribute("stroke","#4a5568");
  line5.setAttribute("stroke-width","2");
  svg.appendChild(line5);

  // BoC step line
  var bocPath = "";
  for(var i=0;i<boc.length;i++){
    var cx = xp(i), cy = yp(boc[i].v);
    if(i===0){ bocPath = "M"+cx+","+cy; }
    else {
      var prevY = yp(boc[i-1].v);
      bocPath += " L"+cx+","+prevY+" L"+cx+","+cy;
    }
  }
  var bocLine = document.createElementNS("http://www.w3.org/2000/svg","path");
  bocLine.setAttribute("d",bocPath);
  bocLine.setAttribute("fill","none");
  bocLine.setAttribute("stroke","#6b7280");
  bocLine.setAttribute("stroke-width","1.5");
  bocLine.setAttribute("stroke-dasharray","4,3");
  svg.appendChild(bocLine);

  // Dots on GoC line
  for(var i=0;i<n;i++){
    svg.appendChild(el("circle",{cx:xp(i),cy:yp(goc[i].v),r:2.5,fill:"#4a5568"}));
  }

  // X-axis labels every 2
  for(var i=0;i<n;i+=2){
    svg.appendChild(el("text",{x:xp(i),y:MT+PH+16,"text-anchor":"middle","font-size":"7.5","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},goc[i].m));
  }

  // Labels at end of each series
  svg.appendChild(el("text",{x:xp(n-1)-4,y:yp(goc[n-1].v)-6,"text-anchor":"end","font-size":"7.5","fill":"#4a5568","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"GoC 5Y"));
  svg.appendChild(el("text",{x:xp(n-1)-4,y:yp(boc[n-1].v)+12,"text-anchor":"end","font-size":"7.5","fill":"#6b7280","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"BoC Rate"));

  // Gold pill on last GoC point
  var lastX = xp(n-1);
  var lastY = yp(goc[n-1].v);
  var pillW = 52, pillH = 16;
  var pillX = lastX - pillW - 6;
  var pillY = lastY - pillH/2;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"3.07%"));

  svg.appendChild(el("line",{x1:ML,x2:ML+PW,y1:MT+PH,y2:MT+PH,stroke:"#d8d8d8","stroke-width":"1"}));

  var con = _cs ? _cs.parentNode : null;
  if(con) con.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: Trading Economics, Bank of Canada selected bond yields; Bank of Canada policy rate announcements. GoC 5Y as of July 2, 2026. &nbsp;|&nbsp; hdq.ca</div>
