<script>
(function(){
  var _cs = document.currentScript;
  var data = [
    {m:"Jan",v:68.2},{m:"Feb",v:78.4},{m:"Mar",v:91.5},
    {m:"Apr",v:95.8},{m:"May",v:93.1},{m:"Jun",v:79.2},
    {m:"Jul",v:68.6}
  ];
  var ML = 54, MR = 24, MT = 22, MB = 42;
  var W = 680, H = 270;
  var PW = W - ML - MR;
  var PH = H - MT - MB;
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 270");
  svg.setAttribute("width","100%");
  var n = data.length;
  var minV = 55, maxV = 105;
  var rng = maxV - minV;
  var barW = 66;
  var gap = (PW - n*barW)/(n+1);

  function xBar(i){return ML + gap*(i+1) + barW*i;}
  function yV(v){return MT + PH*(1-(v-minV)/rng);}

  function el(tag,attrs,txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg",tag);
    for(var k in attrs){e.setAttribute(k,attrs[k]);}
    if(txt!==undefined){e.textContent=txt;}
    return e;
  }

  var ticks = [60,70,80,90,100];
  for(var i=0;i<ticks.length;i++){
    var ty = yV(ticks[i]);
    svg.appendChild(el("line",{x1:ML,x2:ML+PW,y1:ty,y2:ty,stroke:"#ececec","stroke-width":"0.5"}));
    svg.appendChild(el("text",{x:ML-6,y:ty+3,"text-anchor":"end","font-size":"8.5","fill":"#aaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"$"+ticks[i]));
  }

  // Pre-war reference line
  var preWarY = yV(68.0);
  svg.appendChild(el("line",{x1:ML,x2:ML+PW,y1:preWarY,y2:preWarY,stroke:"#2e7d32","stroke-dasharray":"3,3","stroke-width":"1"}));
  svg.appendChild(el("text",{x:ML+6,y:preWarY-4,"text-anchor":"start","font-size":"7","fill":"#2e7d32","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"Pre-war ~$68"));

  // Peak annotation
  var peakY = yV(95.8);
  svg.appendChild(el("text",{x:xBar(3)+barW/2,y:peakY-8,"text-anchor":"middle","font-size":"7","fill":"#8a3030","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"PEAK $96"));

  // Bars
  for(var i=0;i<n;i++){
    var bx = xBar(i);
    var bh = ((data[i].v-minV)/rng)*PH;
    var by = MT + PH - bh;
    var fillColor;
    if(data[i].v >= 88){ fillColor = "#3a7a55"; }
    else if(data[i].v >= 75){ fillColor = "#6b7280"; }
    else { fillColor = "#8a3030"; }
    if(i===n-1){ fillColor = "#8a3030"; }
    svg.appendChild(el("rect",{x:bx,y:by,width:barW,height:bh,fill:fillColor}));
    svg.appendChild(el("text",{x:bx+barW/2,y:by-4,"text-anchor":"middle","font-size":"8","fill":"#666","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"$"+data[i].v.toFixed(0)));
    svg.appendChild(el("text",{x:bx+barW/2,y:MT+PH+14,"text-anchor":"middle","font-size":"8","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},data[i].m));
  }

  // War onset event marker
  var warX = xBar(1) + barW/2;
  svg.appendChild(el("line",{x1:warX,x2:warX,y1:MT,y2:MT+PH,stroke:"#1a3560","stroke-dasharray":"2,3","stroke-width":"1","stroke-opacity":"0.5"}));
  svg.appendChild(el("text",{x:warX+4,y:MT+14,"text-anchor":"start","font-size":"7","fill":"#1a3560","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"Feb 28"));
  svg.appendChild(el("text",{x:warX+4,y:MT+24,"text-anchor":"start","font-size":"7","fill":"#1a3560","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"War onset"));

  // MOU event marker
  var mouX = xBar(5) + barW/2;
  svg.appendChild(el("line",{x1:mouX,x2:mouX,y1:MT,y2:MT+PH,stroke:"#1a3560","stroke-dasharray":"2,3","stroke-width":"1","stroke-opacity":"0.5"}));
  svg.appendChild(el("text",{x:mouX-4,y:MT+14,"text-anchor":"end","font-size":"7","fill":"#1a3560","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"Jun 17"));
  svg.appendChild(el("text",{x:mouX-4,y:MT+24,"text-anchor":"end","font-size":"7","fill":"#1a3560","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"MOU"));

  // Gold pill on last bar
  var lastX = xBar(n-1)+barW/2;
  var lastY = yV(data[n-1].v);
  var pillW = 62, pillH = 16;
  var pillX = lastX - pillW/2;
  var pillY = lastY - pillH - 6;
  svg.appendChild(el("circle",{cx:lastX,cy:lastY,r:4,fill:"#4a5568"}));
  svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,fill:"#e8a825",rx:"3"}));
  svg.appendChild(el("text",{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"9","font-weight":"700","fill":"#111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"$68.56 Jul"));

  svg.appendChild(el("line",{x1:ML,x2:ML+PW,y1:MT+PH,y2:MT+PH,stroke:"#d8d8d8","stroke-width":"1"}));

  var con = _cs ? _cs.parentNode : null;
  if(con) con.appendChild(svg);
})();
</script>
