  svg.appendChild(el("text",{x:650,y:athY-4,"text-anchor":"end","font-size":"7","fill":"#2e7d32","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"ATH 35,629 Jun 17"));

  // Event band: war onset
  var warX1 = xp(8), warX2 = xp(10);
  svg.appendChild(el("rect",{x:warX1,y:MT,width:warX2-warX1,height:PH,fill:"#c0392b","fill-opacity":"0.05"}));
  svg.appendChild(el("text",{x:warX1+3,y:MT+11,"font-size":"7","fill":"#8a3030","font-weight":"700","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},"War"));

  // Line path
  var pts = data.map(function(d,i){return xp(i)+","+yp(d.v);}).join(" ");
  var line = document.createElementNS("http://www.w3.org/2000/svg","polyline");
  line.setAttribute("points",pts);
  line.setAttribute("fill","none");
  line.setAttribute("stroke","#4a5568");
  line.setAttribute("stroke-width","2");
  svg.appendChild(line);

  // Dots every 4 weeks
  for(var i=0;i<n;i+=4){
    svg.appendChild(el("circle",{cx:xp(i),cy:yp(data[i].v),r:2.5,fill:"#4a5568"}));
  }
  // Always dot on last
  svg.appendChild(el("circle",{cx:xp(n-1),cy:yp(data[n-1].v),r:2.5,fill:"#4a5568"}));

  // X-axis labels every 4 weeks
  for(var i=0;i<n;i+=4){
    svg.appendChild(el("text",{x:xp(i),y:MT+PH+14,"text-anchor":"middle","font-size":"7","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},data[i].w));
  }
  svg.appendChild(el("text",{x:xp(n-1),y:MT+PH+14,"text-anchor":"middle","font-size":"7","fill":"#999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"},data[n-1].w));

  // Moving average (8-week)
  var maLen = 8;
  var maPts = [];
  for(var i=maLen-1;i<n;i++){
    var sum = 0;
    for(var j=i-maLen+1;j<=i;j++) sum += data[j].v;
    maPts.push(xp(i)+","+yp(sum/maLen));
